INSERT INTO public.sources AS current_source (id,publisher_id,name,source_kind,fetch_strategy,start_url,parser_config,poll_interval_minutes,next_run_at,respect_robots,terms_reviewed_at,is_active)
SELECT id::uuid,publisher_id::uuid,name,source_kind,'http',start_url,parser_config,poll_interval_minutes,now(),true,now(),true FROM crawlee_sources
ON CONFLICT (id) DO UPDATE SET
  is_active = true,
  terms_reviewed_at = COALESCE(current_source.terms_reviewed_at, now()),
  updated_at = now();

